fun C stream t w =>
  if hall :
      ∀ (n : Nat),
        GenLimit.KleinbergWei.DensityMeasures.StrictCritical C stream t n → Membership.mem.{0, 0} (C n) w then
    GenLimit.KleinbergWei.DensityMeasures.scopedFocus C stream t
  else
    have hbad := ⋯;
    have S := GenLimit.KleinbergWei.DensityMeasures.boundaryCandidates C stream t w;
    if hS : Finset.Nonempty.{0} S then Finset.max'.{0} S hS
    else GenLimit.KleinbergWei.DensityMeasures.scopedFocus C stream t

fun K A n =>
