fun C stream r hr round child =>
  have S := GenLimit.KleinbergWei.DensityMeasures.FiniteRankParent.parentCandidateSet C stream r hr round child;
  if hfin : Set.Finite.{0} S then
    if hne : Finset.Nonempty.{0} (Set.Finite.toFinset.{0} hfin) then
      Option.some.{0} (Finset.max'.{0} (Set.Finite.toFinset.{0} hfin) hne)
    else Option.none.{0}
